def _summary(raw: dict) -> dict:
    return {
        "id": raw["id"],
        "name": raw["name"],
        "sector": raw["sector"],
        "category": raw["category"],
        "version": raw.get("version", 1),
        "description": raw.get("description", ""),
        "section_count": len(raw.get("sections", [])),
        "field_count": sum(len(section.get("fields", [])) for section in raw.get("sections", [])),
        "minimum_evidence": sum(section.get("evidence_min", 0) for section in raw.get("sections", [])),
        "asset_types": raw.get("asset_types", []),
        "source_basis": raw.get("source_basis"),
    }


def _active_definition(row: TemplateDefinition, db: Session) -> dict | None:
    if not row.active_version_id:
        return None
    version = db.get(TemplateVersion, row.active_version_id)
    return version.definition if version else None


@router.get("")
def list_templates(
    sector: str | None = Query(default=None),
    category: str | None = Query(default=None),
    db: Session = Depends(get_db),
) -> list[dict]:
    rows = db.query(TemplateDefinition).all()
    if rows:
        result = []
        for row in rows:
            raw = _active_definition(row, db)
            if not raw:
                continue
            item = _summary(raw)
            item["database_id"] = row.id
            result.append(item)
    else:
        result = [_summary(raw) for raw in LEGACY_TEMPLATES]

    if sector:
        result = [item for item in result if item["sector"].lower() == sector.lower()]
    if category:
        result = [item for item in result if item["category"].lower() == category.lower()]
    return sorted(result, key=lambda item: (item["sector"], item["name"]))


@router.get("/{template_id}")
def get_template(template_id: str, db: Session = Depends(get_db)) -> dict:
    row = db.query(TemplateDefinition).filter(
        (TemplateDefinition.slug == template_id) | (TemplateDefinition.id == template_id)
    ).first()
    if row:
        raw = _active_definition(row, db)
        if raw:
            result = dict(raw)
            result["database_id"] = row.id
            return result

    for raw in LEGACY_TEMPLATES:
        if raw["id"] == template_id:
            return raw
    raise HTTPException(status_code=404, detail="Inspection template not found")


@router.post("/{template_id}/validate")
def validate_template(template_id: str, payload: dict, db: Session = Depends(get_db)) -> dict:
    template = get_template(template_id, db)
    answers = payload.get("answers") or {}
    evidence = payload.get("evidence") or []
    missing_fields = []
    missing_evidence = []

    for section in template.get("sections", []):
        for item in section.get("fields", []):
            if item.get("required") and answers.get(item["key"]) in (None, "", []):
                missing_fields.append({
                    "section_id": section["id"],
                    "field_key": item["key"],
                    "label": item["label"],
                })
        captured = sum(1 for item in evidence if item.get("section_id") == section["id"])
        required = section.get("evidence_min", 0)
        if captured < required:
            missing_evidence.append({
                "section_id": section["id"],
                "section_title": section["title"],
                "required": required,
                "captured": captured,
            })

    return {
        "valid": not missing_fields and not missing_evidence,
        "missing_fields": missing_fields,
        "missing_evidence": missing_evidence,
    }
